from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for row in out:
        positions = [j for j, v in enumerate(row) if v != background]
        if not positions:
            continue
        first, last = min(positions), max(positions)
        # Extend a solid horizontal run with 1s; gaps in the run mark other patterns.
        if all(row[j] != background for j in range(first, last + 1)):
            for j in range(last + 1, len(row)):
                if row[j] == background:
                    row[j] = 1
    return out

def transform(grid):
    bg=min(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    out=[r[:] for r in grid]
    for i,row in enumerate(grid):
        pos=[j for j,v in enumerate(row) if v!=bg]
        if pos:
            for j in range(max(pos)+1,len(row)):
                out[i][j]=1
    return out
